    !isempty(x.sources) && PB.encode(e, 11, x.sources)
    !isempty(x.structures) && PB.encode(e, 12, x.structures)
    !isempty(x.blocks) && PB.encode(e, 13, x.blocks)
    return position(e.io) - initpos
end
function PB._encoded_size(x::Program)
